import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const lower = Math.min(minDistance, maxDistance);
  const upper = Math.max(minDistance, maxDistance);

  const disposeLimits = setCameraLimits(
    camera,
    { lowerRadiusLimit: lower, upperRadiusLimit: upper },
    scene
  );

  const disposeControl = attachControl(camera, canvas, scene, { keyboard: false });

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    disposeControl();
    disposeLimits();
  };
}
```

I used `setCameraLimits` to install the radius bounds and `attachControl` for the normal pointer, wheel, and pinch controls, returning a single dispose function that tears both down. I was not sure whether those helpers are exported from the package root or a subpath, but I imported them from `@babylonjs/lite` as requested.
